declare(strict_types=1);require __DIR__.'/bootstrap.php';require_admin();require_csrf();ensure_dirs();require_seed_table();$sourceId=(int)($_POST['source_record_id']??0);$st=db()->prepare('SELECT * FROM seed_count_records WHERE id=?');$st->execute([$sourceId]);$source=$st->fetch();if(!$source)json_out(['success'=>false,'error'=>'再解析元の記録がありません。'],404);$src=path_of((string)$source['original_path']);if(!is_file($src))json_out(['success'=>false,'error'=>'再解析元の画像がありません。'],404);$info=@getimagesize($src);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!$info||!isset($allowed[$info['mime']]))json_out(['success'=>false,'error'=>'再解析元の画像形式に対応していません。'],415);$job=bin2hex(random_bytes(18));$token=bin2hex(random_bytes(24));$ext=$allowed[$info['mime']];$origRel="uploads/original/$job.$ext";$resRel="uploads/result/$job.jpg";$stageRel="uploads/stages/$job";$orig=path_of($origRel);$res=path_of($resRel);$stage=path_of($stageRel);if(!copy($src,$orig))json_out(['success'=>false,'error'=>'履歴画像を複製できません。'],500);$slot=acquire_slot();if(!$slot){@unlink($orig);json_out(['success'=>false,'error'=>'解析が集中しています。'],503);}
try{$settings=normalize_seed_settings($_POST,seed_settings());$d=run_python(seed_python_args($orig,$res,$settings,$stage));$pdo=db();$pdo->beginTransaction();$sum=$d['summary'];$memo=mb_substr(trim((string)($_POST['memo']??'')),0,220);$memo.=' [再解析元 #'.$sourceId.']';$ins=$pdo->prepare('INSERT INTO seed_count_records(job_id,access_token,device_name,memo,seed_count,original_path,result_path,threshold_value,settings_json,analysis_json,processing_ms,engine,algorithm_version,module_version,mean_area_px2,mean_major_axis_px,mean_minor_axis_px,mean_circularity,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())');$ins->execute([$job,$token,mb_substr(trim((string)($_POST['device_name']??'')),0,100),$memo,(int)$d['count'],$origRel,$resRel,(float)$d['settings']['threshold'],json_encode($d['settings'],JSON_UNESCAPED_UNICODE),json_encode(['summary'=>$d['summary'],'rejected'=>$d['rejected'],'image'=>$d['image'],'watershed'=>$d['watershed'],'stage_path'=>$stageRel,'reanalyzed_from'=>$sourceId],JSON_UNESCAPED_UNICODE),(int)$d['processing_ms'],'Python OpenCV '.$d['engine']['opencv'],$d['engine']['algorithm_version'],(string)cfg('app_version'),$sum['area_px2']['mean'],$sum['major_axis_px']['mean'],$sum['minor_axis_px']['mean'],$sum['circularity']['mean']]);$recordId=(int)$pdo->lastInsertId();$obj=$pdo->prepare('INSERT INTO seed_morphology_objects(record_id,object_number,centroid_x,centroid_y,area_px2,perimeter_px,major_axis_px,minor_axis_px,aspect_ratio,circularity,solidity,extent,convex_hull_area_px2,equivalent_diameter_px,orientation_deg,area_mm2,perimeter_mm,major_axis_mm,minor_axis_mm,quality_class,metrics_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($d['objects']as$o)$obj->execute([$recordId,$o['number'],$o['centroid_x'],$o['centroid_y'],$o['area_px2'],$o['perimeter_px'],$o['major_axis_px'],$o['minor_axis_px'],$o['aspect_ratio'],$o['circularity'],$o['solidity'],$o['extent'],$o['convex_hull_area_px2'],$o['equivalent_diameter_px'],$o['orientation_deg